svg.script:
(async () => {
  const status = document.getElementById('status');

  function setStatus(msg) {
    status.textContent = msg;
    console.log(msg);
  }

  try {
    setStatus("Starting…");

    // Make sure we have a proper base URL
    const base = new URL('./', location.href);
    setStatus("Base: " + base.href);

    // Register the service worker
    setStatus("Registering service worker…");
    const swUrl = new URL('sw.js', base);

    const registration = await navigator.serviceWorker.register(swUrl, {
      scope: base.pathname,
      updateViaCache: 'none'
    });

    setStatus("Service worker registered");

    const worker = registration.active || registration.installing || registration.waiting;
    if (!worker) {
      throw new Error("No service worker found after registration");
    }

    // Wait until the worker is activated
    if (worker.state !== 'activated') {
      setStatus("Waiting for worker to activate… (" + worker.state + ")");
      await new Promise((resolve, reject) => {
        const timeout = setTimeout(() => {
          reject(new Error("Worker took too long to activate"));
        }, 10000);

        function check() {
          setStatus("Worker state: " + worker.state);
          if (worker.state === 'activated') {
            clearTimeout(timeout);
            resolve();
          }
          if (worker.state === 'redundant') {
            clearTimeout(timeout);
            reject(new Error("Worker became redundant"));
          }
        }

        worker.addEventListener('statechange', check);
        check();
      });
    }

    setStatus("Worker activated. Loading index.html…");

    const app = document.getElementById('app');
    app.src = new URL('index.html', base).href;
    app.style.display = 'block';
    status.remove();

  } catch (error) {
    console.error(error);
    setStatus("Failed: " + error.message);
  }
})();
